<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x97F3;&#x9891;&#x8F6C;&#x6362;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="file-area"><view class="pick-btn" @click="pickAudio"><text>{{ fileName || '&#x9009;&#x62E9;&#x97F3;&#x9891;&#x6587;&#x4EF6;' }}</text></view></view><view class="format-section"><text class="section-title">&#x8F93;&#x51FA;&#x683C;&#x5F0F;</text><view class="format-grid"><view class="format-btn" v-for="f in formats" :key="f" :class="{active: outFormat===f}" @click="outFormat=f">{{f}}</view></view></view><view class="bitrate-section"><text class="section-title">&#x7F16;&#x7801;&#x7387;</text><view class="bitrate-row"><view class="bitrate-btn" v-for="b in bitrates" :key="b" :class="{active: bitrate===b}" @click="bitrate=b">{{b}}</view></view></view><view class="convert-btn" @click="startConvert" :class="{disabled: !fileName}"><text>{{ converting ? convertingText : '&#x5F00;&#x59CB;&#x8F6C;&#x6362;' }}</text></view><view v-if="convertDone" class="result-box"><text class="result-text">&#x2705; &#x8F6C;&#x6362;&#x5B8C;&#x6210;</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const fileName = ref("")
const outFormat = ref("MP3")
const bitrate = ref("192kbps")
const formats = ["MP3","WAV","AAC","FLAC","OGG"]
const bitrates = ["128kbps","192kbps","256kbps","320kbps"]
const converting = ref(false)
const convertDone = ref(false)
const convertingText = ref("")
function goBack() { uni.navigateBack() }
function pickAudio() { uni.chooseMessageFile({ count: 1, type: "file", success: function(res) { fileName.value = res.tempFiles[0].name; convertDone.value = false } }) }
function startConvert() { if (!fileName.value) return; converting.value = true; convertDone.value = false; var steps = ["&#x5206;&#x6790;&#x6587;&#x4EF6;...", "\u89E3\u7801\u4E2D...", "\u7F16\u7801\u4E2D...", "\u5B8C\u6210"]; var i = 0; convertingText.value = steps[0]; var timer = setInterval(function() { i++; if (i >= steps.length) { clearInterval(timer); converting.value = false; convertDone.value = true } else { convertingText.value = steps[i] } }, 800) }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#059669,#047857);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.file-area{margin-bottom:24rpx}.pick-btn{background:#fff;border-radius:16rpx;padding:40rpx;text-align:center;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04);border:2rpx dashed #059669}.pick-btn text{font-size:30rpx;color:#059669}.format-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.section-title{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.format-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12rpx}.format-btn{padding:16rpx;text-align:center;background:#f5f7fb;border-radius:12rpx;font-size:26rpx;color:#666}.format-btn.active{background:linear-gradient(135deg,#059669,#047857);color:#fff}.bitrate-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.bitrate-row{display:flex;gap:12rpx}.bitrate-btn{flex:1;padding:16rpx;text-align:center;background:#f5f7fb;border-radius:12rpx;font-size:24rpx;color:#666}.bitrate-btn.active{background:linear-gradient(135deg,#059669,#047857);color:#fff}.convert-btn{background:linear-gradient(135deg,#059669,#047857);border-radius:16rpx;padding:24rpx;text-align:center}.convert-btn text{font-size:30rpx;color:#fff;font-weight:600}.convert-btn.disabled{opacity:.5}.result-box{background:#fff;border-radius:16rpx;padding:24rpx;text-align:center;margin-top:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.result-text{font-size:30rpx;color:#059669;font-weight:600}</style>